from ortools.sat.python import cp_model
import json

def main():
    model = cp_model.CpModel()

    F = ['A', 'B']
    W = {'A': 60, 'B': 70}
    H = {'A': 60, 'B': 50}
    A = {'A': 3600, 'B': 3500}

    P = ['small', 'medium', 'large']
    w = {'small': 20, 'medium': 30, 'large': 25}
    h = {'small': 10, 'medium': 30, 'large': 15}
    a = {'small': 200, 'medium': 900, 'large': 375}

    L = {'small': 2, 'medium': 3, 'large': 2}
    U = {'small': 5, 'medium': 6, 'large': 4}

    use = {}
    for f in F:
        use[f] = model.NewBoolVar(f"use_{f}")

    n = {}
    for p in P:
        n[p] = model.NewIntVar(L[p], U[p], f"n_{p}")

    assign = {}
    x = {}
    y = {}
    r = {}

    for p in P:
        assign[p] = {}
        x[p] = {}
        y[p] = {}
        r[p] = {}
        for i in range(U[p]):
            assign[p][i] = {}
            x[p][i] = {}
            y[p][i] = {}
            r[p][i] = {}
            for f in F:
                assign[p][i][f] = model.NewBoolVar(f"assign_{p}_{i}_{f}")
                x[p][i][f] = model.NewIntVar(0, W[f] - min(w[p], h[p]), f"x_{p}_{i}_{f}")
                y[p][i][f] = model.NewIntVar(0, H[f] - min(w[p], h[p]), f"y_{p}_{i}_{f}")
                r[p][i][f] = model.NewBoolVar(f"r_{p}_{i}_{f}")

    for p in P:
        for i in range(U[p]):
            model.Add(sum(assign[p][i][f] for f in F) <= 1)

    for p in P:
        model.Add(n[p] == sum(assign[p][i][f] for i in range(U[p]) for f in F))

    for p in P:
        for i in range(U[p]):
            for f in F:
                effective_width = model.NewIntVar(0, max(w[p], h[p]), f"eff_w_{p}_{i}_{f}")
                effective_height = model.NewIntVar(0, max(w[p], h[p]), f"eff_h_{p}_{i}_{f}")

                model.Add(effective_width == w[p]).OnlyEnforceIf(r[p][i][f].Not())
                model.Add(effective_width == h[p]).OnlyEnforceIf(r[p][i][f])
                model.Add(effective_height == h[p]).OnlyEnforceIf(r[p][i][f].Not())
                model.Add(effective_height == w[p]).OnlyEnforceIf(r[p][i][f])

                model.Add(x[p][i][f] + effective_width <= W[f]).OnlyEnforceIf(assign[p][i][f])
                model.Add(y[p][i][f] + effective_height <= H[f]).OnlyEnforceIf(assign[p][i][f])

                model.Add(x[p][i][f] == 0).OnlyEnforceIf(assign[p][i][f].Not())
                model.Add(y[p][i][f] == 0).OnlyEnforceIf(assign[p][i][f].Not())
                model.Add(r[p][i][f] == 0).OnlyEnforceIf(assign[p][i][f].Not())

    for f in F:
        x_intervals = []
        y_intervals = []

        for p in P:
            for i in range(U[p]):
                x_size = model.NewIntVar(min(w[p], h[p]), max(w[p], h[p]), f"x_size_{p}_{i}_{f}")
                y_size = model.NewIntVar(min(w[p], h[p]), max(w[p], h[p]), f"y_size_{p}_{i}_{f}")

                model.Add(x_size == w[p]).OnlyEnforceIf(r[p][i][f].Not())
                model.Add(x_size == h[p]).OnlyEnforceIf(r[p][i][f])
                model.Add(y_size == h[p]).OnlyEnforceIf(r[p][i][f].Not())
                model.Add(y_size == w[p]).OnlyEnforceIf(r[p][i][f])

                x_end = model.NewIntVar(0, W[f], f"x_end_{p}_{i}_{f}")
                y_end = model.NewIntVar(0, H[f], f"y_end_{p}_{i}_{f}")

                model.Add(x_end == x[p][i][f] + x_size)
                model.Add(y_end == y[p][i][f] + y_size)

                x_interval = model.NewOptionalIntervalVar(
                    x[p][i][f], x_size, x_end, assign[p][i][f], f"x_interval_{p}_{i}_{f}"
                )
                y_interval = model.NewOptionalIntervalVar(
                    y[p][i][f], y_size, y_end, assign[p][i][f], f"y_interval_{p}_{i}_{f}"
                )

                x_intervals.append(x_interval)
                y_intervals.append(y_interval)

        if x_intervals:
            model.AddNoOverlap2D(x_intervals, y_intervals)

    for f in F:
        for p in P:
            for i in range(U[p]):
                model.AddImplication(assign[p][i][f], use[f])

        total_assign = sum(assign[p][i][f] for p in P for i in range(U[p]))
        model.Add(use[f] <= total_assign)

    total_fabric_area_expr = sum(use[f] * A[f] for f in F)
    total_used_area_expr = sum(n[p] * a[p] for p in P)

    waste_area = model.NewIntVar(0, sum(A[f] for f in F), "waste_area")
    model.Add(waste_area == total_fabric_area_expr - total_used_area_expr)

    model.Minimize(waste_area)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_fabric_area_val = sum(solver.Value(use[f]) * A[f] for f in F)
        total_used_area_val = sum(solver.Value(n[p]) * a[p] for p in P)

        if total_fabric_area_val > 0:
            waste_rate = (total_fabric_area_val - total_used_area_val) / total_fabric_area_val
        else:
            waste_rate = 0.0

        fabric_instances = {}
        for f in F:
            if solver.Value(use[f]) == 1:
                fabric_instances[f] = []
                for p in P:
                    for i in range(U[p]):
                        if solver.Value(assign[p][i][f]) == 1:
                            x_val = solver.Value(x[p][i][f])
                            y_val = solver.Value(y[p][i][f])
                            r_val = solver.Value(r[p][i][f])
                            orientation = "rotated" if r_val == 1 else "normal"
                            fabric_instances[f].append({
                                'piece': p,
                                'x': x_val,
                                'y': y_val,
                                'orientation': orientation
                            })

        piece_counts = {p: solver.Value(n[p]) for p in P}

        result = {
            "waste_rate": waste_rate,
            "fabric_instances": fabric_instances,
            "piece_counts": piece_counts,
            "total_fabric_area": total_fabric_area_val,
            "total_used_area": total_used_area_val
        }
        print(json.dumps(result))

    else:
        result = {
            "waste_rate": 1.0,
            "fabric_instances": {},
            "piece_counts": {p: 0 for p in P},
            "total_fabric_area": 0,
            "total_used_area": 0
        }
        print(json.dumps(result))

if __name__ == "__main__":
    main()
